CREATE OR REPLACE FUNCTION public.apply_payment_fee_ledger_refund(p_ledger_id uuid, p_refunded_gross_cents bigint)
 RETURNS bigint
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_creator_id uuid;
  v_gross bigint;
  v_creator_net bigint;
  v_previous_refunded bigint;
  v_previous_reversed bigint;
  v_platform_fee bigint;
  v_processing_fee bigint;
  v_was_credited boolean;
  v_refunded bigint;
  v_target_reversed bigint;
  v_platform_attribution bigint;
  v_processing_attribution bigint;
  v_rounding_adjustment bigint;
  v_delta bigint;
begin
  select creator_id, gross_amount_cents, creator_net_cents, refunded_amount_cents,
         earnings_reversed_cents, platform_fee_cents, processing_fee_cents,
         earnings_credited_at is not null
  into v_creator_id, v_gross, v_creator_net, v_previous_refunded,
       v_previous_reversed, v_platform_fee, v_processing_fee, v_was_credited
  from public.payment_fee_ledger where id = p_ledger_id for update;
  if not found or v_gross <= 0 then return 0; end if;
  v_refunded := least(v_gross, greatest(v_previous_refunded, p_refunded_gross_cents, 0));
  v_target_reversed := round((v_creator_net::numeric * v_refunded::numeric) / v_gross::numeric);
  v_platform_attribution := round((v_platform_fee::numeric * v_refunded::numeric) / v_gross::numeric);
  v_processing_attribution := round((v_processing_fee::numeric * v_refunded::numeric) / v_gross::numeric);
  v_rounding_adjustment := v_refunded - v_target_reversed - v_platform_attribution - v_processing_attribution;
  v_delta := greatest(0, v_target_reversed - v_previous_reversed);
  if v_delta > 0 and v_was_credited then
    update public.profiles
    set total_earnings_cents = greatest(0, coalesce(total_earnings_cents, 0) - v_delta)
    where id = v_creator_id;
  end if;
  update public.payment_fee_ledger
  set refunded_amount_cents = v_refunded,
      earnings_reversed_cents = v_target_reversed,
      platform_fee_refund_attribution_cents = v_platform_attribution,
      processing_fee_refund_attribution_cents = v_processing_attribution,
      refund_allocation_rounding_cents = v_rounding_adjustment,
      status = case when v_refunded >= v_gross then 'refunded' else status end,
      updated_at = now()
  where id = p_ledger_id;
  return case when v_was_credited then v_delta else 0 end;
end;
$function$

CREATE OR REPLACE FUNCTION public.apply_purchase_refund_earnings(p_purchase_id uuid, p_refunded_gross_cents bigint)
 RETURNS bigint
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_creator_id uuid;
  v_gross bigint;
  v_credited bigint;
  v_previous_refunded bigint;
  v_previous_reversed bigint;
  v_platform_fee bigint;
  v_processing_fee bigint;
  v_refunded bigint;
  v_target_reversed bigint;
  v_platform_attribution bigint;
  v_processing_attribution bigint;
  v_rounding_adjustment bigint;
  v_delta bigint;
  v_subscription_id text;
begin
  select creator_id, coalesce(amount_cents, 0), earnings_credited_cents,
         coalesce(refunded_amount_cents, 0), coalesce(earnings_reversed_cents, 0),
         coalesce(platform_fee_cents, 0), coalesce(processing_fee_cents, 0), subscription_id
  into v_creator_id, v_gross, v_credited, v_previous_refunded, v_previous_reversed,
       v_platform_fee, v_processing_fee, v_subscription_id
  from public.purchases where id = p_purchase_id for update;
  if not found or v_subscription_id is not null or v_creator_id is null
     or v_gross <= 0 or v_credited is null then return 0; end if;
  v_refunded := least(v_gross, greatest(v_previous_refunded, p_refunded_gross_cents, 0));
  v_target_reversed := round((v_credited::numeric * v_refunded::numeric) / v_gross::numeric);
  v_platform_attribution := round((v_platform_fee::numeric * v_refunded::numeric) / v_gross::numeric);
  v_processing_attribution := round((v_processing_fee::numeric * v_refunded::numeric) / v_gross::numeric);
  v_rounding_adjustment := v_refunded - v_target_reversed - v_platform_attribution - v_processing_attribution;
  v_delta := greatest(0, v_target_reversed - v_previous_reversed);
  if v_delta > 0 then
    update public.profiles
    set total_earnings_cents = greatest(0, coalesce(total_earnings_cents, 0) - v_delta)
    where id = v_creator_id;
  end if;
  update public.purchases
  set refunded_amount_cents = v_refunded,
      earnings_reversed_cents = v_target_reversed,
      platform_fee_refund_attribution_cents = v_platform_attribution,
      processing_fee_refund_attribution_cents = v_processing_attribution,
      refund_allocation_rounding_cents = v_rounding_adjustment,
      status = case when v_refunded >= v_gross then 'refunded' else status end,
      access_granted = case when v_refunded >= v_gross then false else access_granted end
  where id = p_purchase_id;
  return v_delta;
end;
$function$

CREATE OR REPLACE FUNCTION public.claim_refund_operation(p_operation_id uuid, p_processing_token uuid, p_lease_seconds integer DEFAULT 300)
 RETURNS text
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_row public.refund_operations%rowtype;
begin
  if p_operation_id is null
     or p_processing_token is null
     or p_lease_seconds < 30
     or p_lease_seconds > 900 then
    raise exception 'invalid refund claim input';
  end if;

  select * into v_row
  from public.refund_operations
  where id = p_operation_id
  for update;

  if not found then return 'missing'; end if;
  if v_row.status = 'completed' then return 'completed'; end if;
  if v_row.status = 'failed' then return 'failed'; end if;

  -- Claims for different operations on the same payment must serialize too.
  -- Otherwise both workers could read the same application-fee amount from
  -- Stripe and each create a cumulative adjustment from that stale baseline.
  perform pg_advisory_xact_lock(
    hashtextextended(v_row.payment_fee_ledger_id::text, 1)
  );
  if exists (
    select 1
    from public.refund_operations other
    where other.payment_fee_ledger_id = v_row.payment_fee_ledger_id
      and other.id <> v_row.id
      and other.processing_token is not null
      and other.processing_claimed_at is not null
      and other.processing_claimed_at >
        now() - make_interval(secs => p_lease_seconds)
  ) then
    return 'busy';
  end if;
  if v_row.processing_token is not null
     and v_row.processing_claimed_at is not null
     and v_row.processing_claimed_at >
       now() - make_interval(secs => p_lease_seconds) then
    return 'busy';
  end if;

  update public.refund_operations
  set processing_token = p_processing_token,
      processing_claimed_at = now(),
      attempt_count = attempt_count + 1,
      updated_at = now()
  where id = p_operation_id;

  return 'claimed';
end;
$function$

CREATE OR REPLACE FUNCTION public.claim_stripe_event(p_event_id text, p_event_type text, p_lease_seconds integer, p_claim_token uuid)
 RETURNS text
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_status text;
  v_claimed_at timestamptz;
begin
  if nullif(trim(p_event_id), '') is null then raise exception 'event id is required'; end if;
  if nullif(trim(p_event_type), '') is null then raise exception 'event type is required'; end if;
  if p_lease_seconds is null or p_lease_seconds < 30 or p_lease_seconds > 3600 then
    raise exception 'event lease must be between 30 and 3600 seconds';
  end if;
  if p_claim_token is null then raise exception 'event claim token is required'; end if;
  insert into public.stripe_events (
    id, type, created_at, status, claimed_at, completed_at, claim_token
  ) values (
    p_event_id, p_event_type, now(), 'processing', now(), null, p_claim_token
  ) on conflict (id) do nothing;
  if found then return 'new'; end if;
  select status, claimed_at into v_status, v_claimed_at
  from public.stripe_events where id = p_event_id for update;
  if not found then raise exception 'event claim row disappeared for %', p_event_id; end if;
  if v_status = 'completed' then return 'duplicate'; end if;
  if v_claimed_at is not null
     and v_claimed_at >= now() - make_interval(secs => p_lease_seconds) then
    return 'busy';
  end if;
  update public.stripe_events
  set type = p_event_type, status = 'processing', claimed_at = now(),
      completed_at = null, claim_token = p_claim_token
  where id = p_event_id;
  return 'new';
end;
$function$

CREATE OR REPLACE FUNCTION public.complete_stripe_event(p_event_id text, p_claim_token uuid)
 RETURNS boolean
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v_completed boolean;
begin
  if nullif(trim(p_event_id), '') is null or p_claim_token is null then
    raise exception 'event id and claim token are required';
  end if;
  update public.stripe_events
  set status = 'completed', completed_at = now()
  where id = p_event_id and status = 'processing' and claim_token = p_claim_token
  returning true into v_completed;
  return coalesce(v_completed, false);
end;
$function$

CREATE OR REPLACE FUNCTION public.create_refund_operation(p_operation_id uuid, p_payment_fee_ledger_id uuid, p_requested_refund_amount_cents bigint, p_reason_code text, p_responsibility text, p_internal_notes text, p_idempotency_key text, p_initiated_by uuid, p_stripe_charge_id text, p_stripe_application_fee_id text, p_stripe_refunded_amount_cents bigint, p_stripe_application_fee_refunded_cents bigint, p_actual_stripe_processing_fee_cents bigint DEFAULT NULL::bigint)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_existing public.refund_operations%rowtype;
  v_ledger public.payment_fee_ledger%rowtype;
  v_booking_id uuid;
  v_previous_refunded bigint;
  v_new_refunded bigint;
  v_previous_app_fee_refunded bigint;
  v_total_fee_before bigint;
  v_total_fee_after bigint;
  v_platform_before bigint;
  v_platform_after bigint;
  v_platform_delta bigint;
  v_processing_before bigint;
  v_processing_after bigint;
  v_processing_delta bigint;
  v_creator_before bigint;
  v_creator_after bigint;
  v_creator_delta bigint;
  v_rounding bigint;
  v_app_fee_delta bigint;
  v_row public.refund_operations%rowtype;
begin
  if p_operation_id is null
     or p_payment_fee_ledger_id is null
     or p_initiated_by is null
     or p_requested_refund_amount_cents is null
     or p_requested_refund_amount_cents <= 0
     or p_idempotency_key is null
     or char_length(p_idempotency_key) < 8
     or char_length(p_idempotency_key) > 200
     or p_stripe_charge_id is null
     or p_stripe_application_fee_id is null
     or p_stripe_refunded_amount_cents is null
     or p_stripe_refunded_amount_cents < 0
     or p_stripe_application_fee_refunded_cents is null
     or p_stripe_application_fee_refunded_cents < 0 then
    raise exception 'invalid refund operation input';
  end if;

  if not exists (
    select 1 from public.profiles
    where id = p_initiated_by and role = 'admin'
  ) then
    raise exception 'initiating user is not an administrator';
  end if;

  -- Serialize retries carrying the same browser-generated idempotency key.
  perform pg_advisory_xact_lock(hashtextextended(p_idempotency_key, 0));

  select * into v_existing
  from public.refund_operations
  where idempotency_key = p_idempotency_key;
  if found then
    return to_jsonb(v_existing);
  end if;

  select * into v_ledger
  from public.payment_fee_ledger
  where id = p_payment_fee_ledger_id
  for update;

  if not found then
    raise exception 'payment ledger row not found';
  end if;
  if v_ledger.status not in ('paid', 'refunded')
     or v_ledger.gross_amount_cents <= 0
     or v_ledger.stripe_payment_intent_id is null then
    raise exception 'payment is not refundable';
  end if;
  if v_ledger.platform_fee_cents
       + v_ledger.processing_fee_cents
       + v_ledger.creator_net_cents
       <> v_ledger.gross_amount_cents then
    raise exception 'immutable payment split is invalid';
  end if;
  if lower(v_ledger.currency) !~ '^[a-z]{3}$' then
    raise exception 'payment currency is invalid';
  end if;
  if p_stripe_refunded_amount_cents > v_ledger.gross_amount_cents then
    raise exception 'Stripe refunded amount exceeds payment gross';
  end if;
  if p_stripe_application_fee_refunded_cents
       > v_ledger.total_creator_deduction_cents then
    raise exception 'Stripe application-fee refund exceeds collected fee';
  end if;
  if p_internal_notes is not null and char_length(p_internal_notes) > 2000 then
    raise exception 'internal notes are too long';
  end if;

  if not (
    (p_reason_code in (
      'creator_non_delivery', 'creator_missed_session',
      'material_misrepresentation', 'creator_discretionary'
    ) and p_responsibility = 'creator')
    or
    (p_reason_code in (
      'duplicate_charge', 'platform_technical_error',
      'incorrect_platform_billing', 'platform_goodwill'
    ) and p_responsibility = 'platform')
    or
    (p_reason_code = 'legally_required' and p_responsibility in ('creator', 'platform'))
  ) then
    raise exception 'refund reason and responsibility do not match';
  end if;

  select greatest(
    coalesce(v_ledger.refunded_amount_cents, 0),
    p_stripe_refunded_amount_cents,
    coalesce(max(cumulative_customer_refund_target_cents), 0)
  ) into v_previous_refunded
  from public.refund_operations
  where payment_fee_ledger_id = p_payment_fee_ledger_id
    and status <> 'failed';

  v_new_refunded := v_previous_refunded + p_requested_refund_amount_cents;
  if v_new_refunded > v_ledger.gross_amount_cents then
    raise exception 'refund exceeds remaining refundable amount';
  end if;

  select greatest(
    p_stripe_application_fee_refunded_cents,
    coalesce(max(application_fee_refund_target_cents), 0)
  ) into v_previous_app_fee_refunded
  from public.refund_operations
  where payment_fee_ledger_id = p_payment_fee_ledger_id
    and status <> 'failed';

  -- First apportion the combined application fee against cumulative refunds,
  -- then split that monotonic target between processing and platform. This
  -- prevents a one-cent refund from independently rounding both components up.
  v_total_fee_before := round(
    v_ledger.total_creator_deduction_cents::numeric * v_previous_refunded::numeric
      / v_ledger.gross_amount_cents::numeric
  );
  v_total_fee_after := round(
    v_ledger.total_creator_deduction_cents::numeric * v_new_refunded::numeric
      / v_ledger.gross_amount_cents::numeric
  );
  if v_ledger.total_creator_deduction_cents = 0 then
    v_processing_before := 0;
    v_processing_after := 0;
  else
    v_processing_before := round(
      v_ledger.processing_fee_cents::numeric * v_total_fee_before::numeric
        / v_ledger.total_creator_deduction_cents::numeric
    );
    v_processing_after := round(
      v_ledger.processing_fee_cents::numeric * v_total_fee_after::numeric
        / v_ledger.total_creator_deduction_cents::numeric
    );
  end if;
  v_platform_before := v_total_fee_before - v_processing_before;
  v_platform_after := v_total_fee_after - v_processing_after;
  v_platform_delta := v_platform_after - v_platform_before;
  v_processing_delta := v_processing_after - v_processing_before;

  v_creator_before := round(
    v_ledger.creator_net_cents::numeric * v_previous_refunded::numeric
      / v_ledger.gross_amount_cents::numeric
  );
  v_creator_after := round(
    v_ledger.creator_net_cents::numeric * v_new_refunded::numeric
      / v_ledger.gross_amount_cents::numeric
  );
  v_creator_delta := v_creator_after - v_creator_before;
  v_rounding := p_requested_refund_amount_cents
    - v_platform_delta - v_processing_delta - v_creator_delta;

  v_app_fee_delta := v_platform_delta
    + case when p_responsibility = 'platform' then v_processing_delta else 0 end;

  if v_previous_app_fee_refunded + v_app_fee_delta
       > v_ledger.total_creator_deduction_cents then
    raise exception 'application-fee refund target exceeds collected fee';
  end if;

  if v_ledger.booking_payment_id is not null then
    select booking_id into v_booking_id
    from public.booking_payments
    where id = v_ledger.booking_payment_id;
  end if;

  insert into public.refund_operations (
    id,
    payment_fee_ledger_id,
    order_id,
    purchase_id,
    booking_id,
    booking_payment_id,
    creator_id,
    stripe_payment_intent_id,
    stripe_charge_id,
    stripe_application_fee_id,
    requested_refund_amount_cents,
    customer_refund_amount_cents,
    currency,
    reason_code,
    responsibility,
    gross_amount_cents,
    platform_fee_cents,
    processing_fee_cents,
    creator_net_cents,
    actual_stripe_processing_fee_cents,
    refunded_before_cents,
    cumulative_customer_refund_target_cents,
    remaining_refundable_cents,
    creator_earnings_reversal_cents,
    creator_balance_impact_cents,
    platform_fee_refund_amount_cents,
    processing_fee_allocation_cents,
    allocation_rounding_cents,
    application_fee_refunded_before_cents,
    application_fee_refund_amount_cents,
    application_fee_refund_target_cents,
    idempotency_key,
    initiated_by,
    internal_notes
  ) values (
    p_operation_id,
    v_ledger.id,
    v_ledger.order_id,
    v_ledger.purchase_id,
    v_booking_id,
    v_ledger.booking_payment_id,
    v_ledger.creator_id,
    v_ledger.stripe_payment_intent_id,
    p_stripe_charge_id,
    p_stripe_application_fee_id,
    p_requested_refund_amount_cents,
    p_requested_refund_amount_cents,
    lower(v_ledger.currency),
    p_reason_code,
    p_responsibility,
    v_ledger.gross_amount_cents,
    v_ledger.platform_fee_cents,
    v_ledger.processing_fee_cents,
    v_ledger.creator_net_cents,
    coalesce(p_actual_stripe_processing_fee_cents, v_ledger.actual_stripe_fee_cents),
    v_previous_refunded,
    v_new_refunded,
    v_ledger.gross_amount_cents - v_new_refunded,
    v_creator_delta,
    p_requested_refund_amount_cents - v_app_fee_delta,
    v_platform_delta,
    v_processing_delta,
    v_rounding,
    v_previous_app_fee_refunded,
    v_app_fee_delta,
    v_previous_app_fee_refunded + v_app_fee_delta,
    p_idempotency_key,
    p_initiated_by,
    nullif(btrim(p_internal_notes), '')
  ) returning * into v_row;

  insert into public.admin_actions (
    actor_id, action, target_table, target_id, reason
  ) values (
    p_initiated_by,
    'create_refund',
    'refund_operations',
    v_row.id,
    p_reason_code || ':' || p_responsibility
  );

  return to_jsonb(v_row);
end;
$function$

CREATE OR REPLACE FUNCTION public.credit_payment_fee_ledger_earnings(p_ledger_id uuid)
 RETURNS boolean
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_creator_id uuid;
  v_creator_net bigint;
  v_already_reversed bigint;
  v_purchase_id uuid;
begin
  select creator_id, creator_net_cents, earnings_reversed_cents, purchase_id
  into v_creator_id, v_creator_net, v_already_reversed, v_purchase_id
  from public.payment_fee_ledger
  where id = p_ledger_id and stripe_invoice_id is not null
    and status in ('paid', 'refunded') and earnings_credited_at is null
  for update;
  if not found then return false; end if;
  update public.profiles
  set total_earnings_cents = coalesce(total_earnings_cents, 0)
    + greatest(0, v_creator_net - coalesce(v_already_reversed, 0))
  where id = v_creator_id;
  if not found then raise exception 'creator profile not found for payment fee ledger %', p_ledger_id; end if;
  if v_purchase_id is null then raise exception 'purchase is missing for recurring payment fee ledger %', p_ledger_id; end if;
  update public.purchases
  set paid_count = coalesce(paid_count, 0) + 1,
      access_granted = true,
      status = case
        when coalesce(paid_count, 0) + 1 >= greatest(coalesce(target_months, 1), 1)
          then 'complete'
        else 'active'
      end
  where id = v_purchase_id and subscription_id is not null
    and coalesce(status, 'pending') <> 'refunded';
  if not found then raise exception 'eligible purchase not found for payment fee ledger %', p_ledger_id; end if;
  update public.payment_fee_ledger
  set earnings_credited_at = now(), updated_at = now()
  where id = p_ledger_id;
  return true;
end;
$function$

CREATE OR REPLACE FUNCTION public.record_payment_dispute_state(p_dispute_id text, p_payment_intent_id text, p_charge_id text, p_disputed_amount_cents bigint, p_currency text, p_status text, p_event_created bigint)
 RETURNS boolean
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v_recorded boolean;
begin
  if nullif(trim(p_dispute_id), '') is null
     or nullif(trim(p_payment_intent_id), '') is null
     or nullif(trim(p_charge_id), '') is null then
    raise exception 'dispute, payment intent, and charge ids are required';
  end if;
  if p_disputed_amount_cents is null or p_disputed_amount_cents < 0 then
    raise exception 'disputed amount must be nonnegative';
  end if;
  if nullif(trim(p_currency), '') is null or nullif(trim(p_status), '') is null then
    raise exception 'dispute currency and status are required';
  end if;
  if p_event_created is null or p_event_created < 0 then
    raise exception 'Stripe event-created time is invalid';
  end if;
  insert into public.payment_dispute_state (
    stripe_dispute_id, stripe_payment_intent_id, stripe_charge_id,
    disputed_amount_cents, currency, status, stripe_event_created
  ) values (
    p_dispute_id, p_payment_intent_id, p_charge_id,
    p_disputed_amount_cents, lower(p_currency), p_status, p_event_created
  )
  on conflict (stripe_dispute_id) do update
  set stripe_payment_intent_id = excluded.stripe_payment_intent_id,
      stripe_charge_id = excluded.stripe_charge_id,
      disputed_amount_cents = excluded.disputed_amount_cents,
      currency = excluded.currency,
      status = excluded.status,
      stripe_event_created = excluded.stripe_event_created,
      updated_at = now()
  where excluded.stripe_event_created >= payment_dispute_state.stripe_event_created
  returning true into v_recorded;
  return coalesce(v_recorded, false);
end;
$function$

CREATE OR REPLACE FUNCTION public.record_payment_refund_state(p_payment_intent_id text, p_charge_id text, p_charge_amount_cents bigint, p_refunded_amount_cents bigint)
 RETURNS bigint
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v_refunded bigint;
begin
  if nullif(trim(p_payment_intent_id), '') is null then raise exception 'payment intent id is required'; end if;
  if nullif(trim(p_charge_id), '') is null then raise exception 'charge id is required'; end if;
  if p_charge_amount_cents is null or p_charge_amount_cents < 0 then
    raise exception 'charge amount must be nonnegative';
  end if;
  if p_refunded_amount_cents is null or p_refunded_amount_cents < 0
     or p_refunded_amount_cents > p_charge_amount_cents then
    raise exception 'refunded amount must be between zero and the charge amount';
  end if;
  insert into public.payment_refund_state (
    stripe_payment_intent_id, stripe_charge_id, charge_amount_cents, refunded_amount_cents
  ) values (
    p_payment_intent_id, p_charge_id, p_charge_amount_cents, p_refunded_amount_cents
  )
  on conflict (stripe_payment_intent_id) do update
  set stripe_charge_id = excluded.stripe_charge_id,
      charge_amount_cents = greatest(payment_refund_state.charge_amount_cents, excluded.charge_amount_cents),
      refunded_amount_cents = least(
        greatest(payment_refund_state.charge_amount_cents, excluded.charge_amount_cents),
        greatest(payment_refund_state.refunded_amount_cents, excluded.refunded_amount_cents)
      ),
      updated_at = now()
  returning refunded_amount_cents into v_refunded;
  return v_refunded;
end;
$function$

CREATE OR REPLACE FUNCTION public.release_stripe_event(p_event_id text, p_claim_token uuid)
 RETURNS boolean
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v_released boolean;
begin
  if nullif(trim(p_event_id), '') is null or p_claim_token is null then
    raise exception 'event id and claim token are required';
  end if;
  delete from public.stripe_events
  where id = p_event_id and status = 'processing' and claim_token = p_claim_token
  returning true into v_released;
  return coalesce(v_released, false);
end;
$function$
